#!/bin/bash

# Installation folder and identity of the Raspberry (generated by setup_identity.py)
APP_DIR="$HOME/AppelerMamie"
IDENTITY_FILE="$APP_DIR/identity.json"

sleep 15

# Remove the Chromium locks
rm -rf "$HOME"/.config/chromium/Singleton* 2>/dev/null

# Read the identifier and the secret of the Raspberry
DEVICE_ID=$(python3 -c 'import json, sys; print(json.load(open(sys.argv[1]))["raspberryId"])' "$IDENTITY_FILE")
DEVICE_SECRET=$(python3 -c 'import json, sys; print(json.load(open(sys.argv[1]))["deviceSecret"])' "$IDENTITY_FILE")

# Language of the TV screen: LANGUAGE in config.py ("fr" if it cannot be read)
LANGUAGE=$(cd "$APP_DIR" && python3 -c 'import config; print(config.LANGUAGE)' 2>/dev/null || echo "fr")

# Server of the TV page: the one of the agent, SERVER_URL in config.py
# ("wss://appelermami.fr" -> "appelermami.fr"; see also switch_server.sh).
# Production server if it cannot be read (change it if the domain changes).
SERVER_HOST=$(cd "$APP_DIR" && python3 -c 'import config; print(config.SERVER_URL.split("://", 1)[1].rstrip("/"))' 2>/dev/null || echo "appelermami.fr")

# Start Chromium
#   --use-fake-ui-for-media-stream: answers "Allow" to the camera/microphone
#     question (the real devices are used; nobody can click in kiosk mode)
#   --autoplay-policy=...: the call sound plays even when the call is accepted
#     with the mouse button (no click inside the page)
#   --disable-features=WebRtcPipeWireCamera: opens the webcam directly (V4L2).
#     Recent Chromium versions go through the desktop camera portal (PipeWire),
#     which a system service cannot reach: the camera never starts.
#   --password-store=basic: no password keyring (nothing to unlock at start)
# 4K TV: 1920 x 1080 first (display_mode.py, lighter for the Raspberry; the
# agent checks it again every 30 s). Never blocks the start of Chromium.
(cd "$APP_DIR" && timeout 15 python3 display_mode.py) || true

DISPLAY=:0 chromium \
  --kiosk \
  --disable-features=WebRtcPipeWireCamera \
  --password-store=basic \
  --use-fake-ui-for-media-stream \
  --autoplay-policy=no-user-gesture-required \
  --no-first-run \
  --no-default-browser-check \
  --disable-translate \
  --disable-background-networking \
  --disable-client-side-phishing-detection \
  --disable-component-extensions-with-background-pages \
  --disable-default-apps \
  --disable-extensions \
  --disable-sync \
  --metrics-recording-only \
  "https://${SERVER_HOST}/receveur.html?id=${DEVICE_ID}&lang=${LANGUAGE}#secret=${DEVICE_SECRET}" &
KIOSK=$!

# Second screen on the other micro-HDMI (display_mode.py --second): the touch
# page opens as an "app" window of the same Chromium (same profile: the two
# pages talk through BroadcastChannel). Its window is named after its address,
# so the labwc rule written by install.sh moves it to HDMI-A-2; the kiosk
# makes it fullscreen. Never the secret: the touch page does not connect to
# the server, the TV page does everything.
if (cd "$APP_DIR" && timeout 15 python3 display_mode.py --second) >/dev/null 2>&1; then
  sleep 5
  DISPLAY=:0 chromium --app="https://${SERVER_HOST}/ecran.html?id=${DEVICE_ID}&lang=${LANGUAGE}" >/dev/null 2>&1 || true
fi

# The service lives as long as the kiosk Chromium (Restart=always)
wait "$KIOSK"
exit 0
